package javaBasics;

public class WrapperClasses {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		//auto boxing
		Integer a = 5;
		
		//auto unboxing
		int b = a;
		
		
		//boxing
		Integer c = Integer.valueOf(10);
		
		//unboxing
		int d = c.intValue();

	}

}
